<span class="line"><span style="color:#61AFEF;">    listen</span><span style="color:#D19A66;"> 443</span><span style="color:#98C379;"> ssl</span><span style="color:#98C379;"> http2</span><span style="color:#ABB2BF;">;</span></span>
