<span class="line"><span style="color:#61AFEF;">    ssl_ciphers</span><span style="color:#98C379;"> ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256</span><span style="color:#ABB2BF;">;</span></span>
